-- LAB-F DRIFT SENTINEL: PRODUCTION EXPORT (SELECT only, read-only).
-- Generated by sportsassets.lab.drift_runner --export-sql from the
-- SAME SELECT statements the read-only endpoint runs
-- (sportsassets/lab/drift_reads.py), with literal arguments:
--   clock 1791145620.0, since 1789936020.0, ref_max_s 604800.0, cmp_max_s 259200.0.
-- Output rows: LABDRIFT|<source>#cols|[names], then one
-- LABDRIFT|<source>|[values] per row; the parser
-- (drift_runner --from-log) applies point_in_time() and the pure
-- sentinel exactly as the endpoint does. Bounded by LIMITs.

\echo === LABDRIFT relations present
SELECT 'LABDRIFT|meta|' || json_build_object('clock', 1791145620.0, 'since', 1789936020.0, 'ref_max_s', 604800.0, 'cmp_max_s', 259200.0)::text AS line;
SELECT 'LABDRIFT|relations|' || json_object_agg(k, v)::text AS line FROM (VALUES ('decisions', to_regclass('paper_decisions') IS NOT NULL), ('orders', to_regclass('paper_orders') IS NOT NULL), ('fills', to_regclass('paper_fills') IS NOT NULL), ('eddie', to_regclass('eddie_execution_outcomes') IS NOT NULL), ('econ', to_regclass('pos_position_economics') IS NOT NULL), ('sleeves', to_regclass('paper_sleeve_classifications') IS NOT NULL), ('settlements', to_regclass('paper_settlements') IS NOT NULL), ('canonical_executions', to_regclass('canonical_intent_executions') IS NOT NULL), ('execmirror_orders', to_regclass('execmirror_orders') IS NOT NULL), ('execmirror_fills', to_regclass('execmirror_fills') IS NOT NULL), ('bettor_funded_fills', to_regclass('bettor_funded_fills') IS NOT NULL), ('kalshi_live_fills', to_regclass('kalshi_live_fills') IS NOT NULL)) AS r(k, v);
\echo === LABDRIFT versions
SELECT 'LABDRIFT|versions#cols|' || (SELECT json_agg(e.key) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT d.strategy, d.policy_version,        d.policy_decision->'parameters'->>'version_id' AS param_version_id,        extract(epoch FROM min(d.decided_at))::float8 AS first_at,        extract(epoch FROM max(d.decided_at))::float8 AS last_at,        extract(epoch FROM max(d.recorded_at))::float8 AS recorded_at,        count(*)::int AS n,        count(*) FILTER (WHERE d.verdict = 'ENTER')::int AS enter_n   FROM paper_decisions d  WHERE d.decided_at <= to_timestamp(1791145620.0)    AND d.recorded_at <= to_timestamp(1791145620.0)  GROUP BY 1, 2, 3  ORDER BY 1, 4) q LIMIT 1;
SELECT 'LABDRIFT|versions|' || (SELECT json_agg(e.value) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT d.strategy, d.policy_version,        d.policy_decision->'parameters'->>'version_id' AS param_version_id,        extract(epoch FROM min(d.decided_at))::float8 AS first_at,        extract(epoch FROM max(d.decided_at))::float8 AS last_at,        extract(epoch FROM max(d.recorded_at))::float8 AS recorded_at,        count(*)::int AS n,        count(*) FILTER (WHERE d.verdict = 'ENTER')::int AS enter_n   FROM paper_decisions d  WHERE d.decided_at <= to_timestamp(1791145620.0)    AND d.recorded_at <= to_timestamp(1791145620.0)  GROUP BY 1, 2, 3  ORDER BY 1, 4) q;
\echo === LABDRIFT latest
SELECT 'LABDRIFT|latest#cols|' || (SELECT json_agg(e.key) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT DISTINCT ON (d.strategy) d.strategy, d.policy_version,        d.policy_decision->'parameters'->>'version_id' AS param_version_id, d.decision_id,        extract(epoch FROM d.decided_at)::float8 AS t,        extract(epoch FROM d.recorded_at)::float8 AS recorded_at   FROM paper_decisions d  WHERE d.decided_at <= to_timestamp(1791145620.0)    AND d.recorded_at <= to_timestamp(1791145620.0)  ORDER BY d.strategy, d.decided_at DESC, d.decision_id DESC) q LIMIT 1;
SELECT 'LABDRIFT|latest|' || (SELECT json_agg(e.value) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT DISTINCT ON (d.strategy) d.strategy, d.policy_version,        d.policy_decision->'parameters'->>'version_id' AS param_version_id, d.decision_id,        extract(epoch FROM d.decided_at)::float8 AS t,        extract(epoch FROM d.recorded_at)::float8 AS recorded_at   FROM paper_decisions d  WHERE d.decided_at <= to_timestamp(1791145620.0)    AND d.recorded_at <= to_timestamp(1791145620.0)  ORDER BY d.strategy, d.decided_at DESC, d.decision_id DESC) q;
\echo === LABDRIFT orders
SELECT 'LABDRIFT|orders#cols|' || (SELECT json_agg(e.key) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT o.order_id, o.strategy, o.group_id, o.decision_id,        extract(epoch FROM o.decided_at)::float8 AS t,        extract(epoch FROM o.created_at)::float8 AS recorded_at,        extract(epoch FROM o.terminal_at)::float8 AS terminal_at,        o.terminal_reason, o.qty::float8 AS qty,        o.us_market_slug, o.holding_side,        d.policy_version, d.policy_decision->'parameters'->>'version_id' AS param_version_id,        extract(epoch FROM d.recorded_at)::float8            AS decision_recorded_at,        d.label->>'competition' AS competition, ev.sport_family,        (SELECT coalesce(sum(f.qty), 0)::float8 FROM paper_fills f          WHERE f.order_id = o.order_id            AND f.recorded_at <= to_timestamp(1791145620.0)) AS filled_qty   FROM paper_orders o   JOIN paper_decisions d ON d.decision_id = o.decision_id   LEFT JOIN external_valuations ev ON ev.id = d.valuation_id  WHERE o.role = 'ENTRY'    AND o.decided_at >= to_timestamp(1789936020.0)    AND o.decided_at <= to_timestamp(1791145620.0)    AND o.created_at <= to_timestamp(1791145620.0)    AND d.recorded_at <= to_timestamp(1791145620.0)  ORDER BY o.decided_at, o.order_id  LIMIT 20000) q LIMIT 1;
SELECT 'LABDRIFT|orders|' || (SELECT json_agg(e.value) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT o.order_id, o.strategy, o.group_id, o.decision_id,        extract(epoch FROM o.decided_at)::float8 AS t,        extract(epoch FROM o.created_at)::float8 AS recorded_at,        extract(epoch FROM o.terminal_at)::float8 AS terminal_at,        o.terminal_reason, o.qty::float8 AS qty,        o.us_market_slug, o.holding_side,        d.policy_version, d.policy_decision->'parameters'->>'version_id' AS param_version_id,        extract(epoch FROM d.recorded_at)::float8            AS decision_recorded_at,        d.label->>'competition' AS competition, ev.sport_family,        (SELECT coalesce(sum(f.qty), 0)::float8 FROM paper_fills f          WHERE f.order_id = o.order_id            AND f.recorded_at <= to_timestamp(1791145620.0)) AS filled_qty   FROM paper_orders o   JOIN paper_decisions d ON d.decision_id = o.decision_id   LEFT JOIN external_valuations ev ON ev.id = d.valuation_id  WHERE o.role = 'ENTRY'    AND o.decided_at >= to_timestamp(1789936020.0)    AND o.decided_at <= to_timestamp(1791145620.0)    AND o.created_at <= to_timestamp(1791145620.0)    AND d.recorded_at <= to_timestamp(1791145620.0)  ORDER BY o.decided_at, o.order_id  LIMIT 20000) q;
\echo === LABDRIFT eddie
SELECT 'LABDRIFT|eddie#cols|' || (SELECT json_agg(e.key) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT DISTINCT ON (o.decision_id, o.source) o.outcome_id,        o.decision_id, o.source,        extract(epoch FROM o.created_at)::float8 AS recorded_at,        o.realized_slippage_pp, o.realized_adverse_selection_pp,        (o.unmeasured ? 'realized_adverse_selection')            AS adverse_selection_unmeasured,        d.strategy, d.policy_version,        d.policy_decision->'parameters'->>'version_id' AS param_version_id,        extract(epoch FROM d.decided_at)::float8 AS t,        extract(epoch FROM d.recorded_at)::float8            AS decision_recorded_at,        d.us_market_slug, d.holding_side,        d.label->>'competition' AS competition, ev.sport_family   FROM eddie_execution_outcomes o   JOIN paper_decisions d ON d.decision_id = o.decision_id   LEFT JOIN external_valuations ev ON ev.id = d.valuation_id  WHERE o.created_at <= to_timestamp(1791145620.0)    AND d.recorded_at <= to_timestamp(1791145620.0)    AND d.decided_at >= to_timestamp(1789936020.0)    AND d.decided_at <= to_timestamp(1791145620.0)  ORDER BY o.decision_id, o.source, o.created_at DESC, o.outcome_id DESC  LIMIT 20000) q LIMIT 1;
SELECT 'LABDRIFT|eddie|' || (SELECT json_agg(e.value) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT DISTINCT ON (o.decision_id, o.source) o.outcome_id,        o.decision_id, o.source,        extract(epoch FROM o.created_at)::float8 AS recorded_at,        o.realized_slippage_pp, o.realized_adverse_selection_pp,        (o.unmeasured ? 'realized_adverse_selection')            AS adverse_selection_unmeasured,        d.strategy, d.policy_version,        d.policy_decision->'parameters'->>'version_id' AS param_version_id,        extract(epoch FROM d.decided_at)::float8 AS t,        extract(epoch FROM d.recorded_at)::float8            AS decision_recorded_at,        d.us_market_slug, d.holding_side,        d.label->>'competition' AS competition, ev.sport_family   FROM eddie_execution_outcomes o   JOIN paper_decisions d ON d.decision_id = o.decision_id   LEFT JOIN external_valuations ev ON ev.id = d.valuation_id  WHERE o.created_at <= to_timestamp(1791145620.0)    AND d.recorded_at <= to_timestamp(1791145620.0)    AND d.decided_at >= to_timestamp(1789936020.0)    AND d.decided_at <= to_timestamp(1791145620.0)  ORDER BY o.decision_id, o.source, o.created_at DESC, o.outcome_id DESC  LIMIT 20000) q;
\echo === LABDRIFT econ
SELECT 'LABDRIFT|econ#cols|' || (SELECT json_agg(e.key) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT x.*,        c.c_policy_version, c.sleeve_optional_recorded_at,        d.policy_version, d.policy_decision->'parameters'->>'version_id' AS param_version_id,        d.strategy AS decision_strategy,        extract(epoch FROM d.recorded_at)::float8            AS decision_optional_recorded_at,        d.label->>'competition' AS competition, ev.sport_family   FROM (     SELECT DISTINCT ON (e.book, e.position_key) e.econ_id, e.book,            e.position_key, e.group_id, e.strategy, e.state,            e.revision,            extract(epoch FROM e.computed_at)::float8 AS recorded_at,            extract(epoch FROM e.released_at)::float8 AS t,            e.time_committed_h, e.us_market_slug, e.holding_side       FROM pos_position_economics e      WHERE e.book IN ('PAPER', 'ACTUAL')        AND e.computed_at <= to_timestamp(1791145620.0)      ORDER BY e.book, e.position_key, e.revision DESC) x   LEFT JOIN LATERAL (     SELECT c.policy_version AS c_policy_version, c.decision_id,            extract(epoch FROM c.classified_at)::float8                AS sleeve_optional_recorded_at       FROM paper_sleeve_classifications c      WHERE c.group_id = x.group_id        AND c.classified_at <= to_timestamp(1791145620.0)      ORDER BY c.classified_at DESC, c.classification_id DESC      LIMIT 1) c ON true   LEFT JOIN paper_decisions d ON d.decision_id = c.decision_id         AND d.recorded_at <= to_timestamp(1791145620.0)   LEFT JOIN external_valuations ev ON ev.id = d.valuation_id  WHERE x.state = 'CLOSED'    AND x.t >= 1789936020.0::float8 AND x.t <= 1791145620.0::float8  ORDER BY x.t, x.position_key  LIMIT 20000) q LIMIT 1;
SELECT 'LABDRIFT|econ|' || (SELECT json_agg(e.value) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT x.*,        c.c_policy_version, c.sleeve_optional_recorded_at,        d.policy_version, d.policy_decision->'parameters'->>'version_id' AS param_version_id,        d.strategy AS decision_strategy,        extract(epoch FROM d.recorded_at)::float8            AS decision_optional_recorded_at,        d.label->>'competition' AS competition, ev.sport_family   FROM (     SELECT DISTINCT ON (e.book, e.position_key) e.econ_id, e.book,            e.position_key, e.group_id, e.strategy, e.state,            e.revision,            extract(epoch FROM e.computed_at)::float8 AS recorded_at,            extract(epoch FROM e.released_at)::float8 AS t,            e.time_committed_h, e.us_market_slug, e.holding_side       FROM pos_position_economics e      WHERE e.book IN ('PAPER', 'ACTUAL')        AND e.computed_at <= to_timestamp(1791145620.0)      ORDER BY e.book, e.position_key, e.revision DESC) x   LEFT JOIN LATERAL (     SELECT c.policy_version AS c_policy_version, c.decision_id,            extract(epoch FROM c.classified_at)::float8                AS sleeve_optional_recorded_at       FROM paper_sleeve_classifications c      WHERE c.group_id = x.group_id        AND c.classified_at <= to_timestamp(1791145620.0)      ORDER BY c.classified_at DESC, c.classification_id DESC      LIMIT 1) c ON true   LEFT JOIN paper_decisions d ON d.decision_id = c.decision_id         AND d.recorded_at <= to_timestamp(1791145620.0)   LEFT JOIN external_valuations ev ON ev.id = d.valuation_id  WHERE x.state = 'CLOSED'    AND x.t >= 1789936020.0::float8 AND x.t <= 1791145620.0::float8  ORDER BY x.t, x.position_key  LIMIT 20000) q;
\echo === LABDRIFT settlements
SELECT 'LABDRIFT|settlements#cols|' || (SELECT json_agg(e.key) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT x.*,        c.c_policy_version, c.sleeve_optional_recorded_at,        d.policy_version, d.policy_decision->'parameters'->>'version_id' AS param_version_id,        d.strategy AS decision_strategy,        extract(epoch FROM d.recorded_at)::float8            AS decision_optional_recorded_at,        d.label->>'competition' AS competition, ev.sport_family   FROM (     SELECT DISTINCT ON (s.position_key) s.settlement_id,            s.position_key, s.group_id, s.outcome, s.version,            s.us_market_slug, s.holding_side,            extract(epoch FROM s.settled_at)::float8 AS t,            extract(epoch FROM s.recorded_at)::float8 AS recorded_at       FROM paper_settlements s      WHERE s.recorded_at <= to_timestamp(1791145620.0)      ORDER BY s.position_key, s.version DESC) x   LEFT JOIN LATERAL (     SELECT c.policy_version AS c_policy_version, c.decision_id,            extract(epoch FROM c.classified_at)::float8                AS sleeve_optional_recorded_at       FROM paper_sleeve_classifications c      WHERE c.group_id = x.group_id        AND c.classified_at <= to_timestamp(1791145620.0)      ORDER BY c.classified_at DESC, c.classification_id DESC      LIMIT 1) c ON true   LEFT JOIN paper_decisions d ON d.decision_id = c.decision_id         AND d.recorded_at <= to_timestamp(1791145620.0)   LEFT JOIN external_valuations ev ON ev.id = d.valuation_id  WHERE x.t >= 1789936020.0::float8 AND x.t <= 1791145620.0::float8  ORDER BY x.t, x.position_key  LIMIT 20000) q LIMIT 1;
SELECT 'LABDRIFT|settlements|' || (SELECT json_agg(e.value) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT x.*,        c.c_policy_version, c.sleeve_optional_recorded_at,        d.policy_version, d.policy_decision->'parameters'->>'version_id' AS param_version_id,        d.strategy AS decision_strategy,        extract(epoch FROM d.recorded_at)::float8            AS decision_optional_recorded_at,        d.label->>'competition' AS competition, ev.sport_family   FROM (     SELECT DISTINCT ON (s.position_key) s.settlement_id,            s.position_key, s.group_id, s.outcome, s.version,            s.us_market_slug, s.holding_side,            extract(epoch FROM s.settled_at)::float8 AS t,            extract(epoch FROM s.recorded_at)::float8 AS recorded_at       FROM paper_settlements s      WHERE s.recorded_at <= to_timestamp(1791145620.0)      ORDER BY s.position_key, s.version DESC) x   LEFT JOIN LATERAL (     SELECT c.policy_version AS c_policy_version, c.decision_id,            extract(epoch FROM c.classified_at)::float8                AS sleeve_optional_recorded_at       FROM paper_sleeve_classifications c      WHERE c.group_id = x.group_id        AND c.classified_at <= to_timestamp(1791145620.0)      ORDER BY c.classified_at DESC, c.classification_id DESC      LIMIT 1) c ON true   LEFT JOIN paper_decisions d ON d.decision_id = c.decision_id         AND d.recorded_at <= to_timestamp(1791145620.0)   LEFT JOIN external_valuations ev ON ev.id = d.valuation_id  WHERE x.t >= 1789936020.0::float8 AND x.t <= 1791145620.0::float8  ORDER BY x.t, x.position_key  LIMIT 20000) q;
\echo === LABDRIFT shadow_execmirror
SELECT 'LABDRIFT|shadow_execmirror#cols|' || (SELECT json_agg(e.key) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT state, count(*)::int AS n   FROM execmirror_orders  WHERE created_at >= to_timestamp(1789936020.0)    AND created_at <= to_timestamp(1791145620.0)  GROUP BY state ORDER BY state) q LIMIT 1;
SELECT 'LABDRIFT|shadow_execmirror|' || (SELECT json_agg(e.value) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT state, count(*)::int AS n   FROM execmirror_orders  WHERE created_at >= to_timestamp(1789936020.0)    AND created_at <= to_timestamp(1791145620.0)  GROUP BY state ORDER BY state) q;
