SELECT 'LABDRIFT|actual_execmirror_fills|' || (SELECT json_agg(e.value) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT count(*)::int AS n FROM execmirror_fills  WHERE observed_at >= to_timestamp(1789936020.0)    AND observed_at <= to_timestamp(1791145620.0)) q;
