SELECT 'LABDRIFT|actual_bettor_funded_fills|' || (SELECT json_agg(e.value) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT count(*)::int AS n FROM bettor_funded_fills  WHERE recorded_at >= to_timestamp(1789936020.0)    AND recorded_at <= to_timestamp(1791145620.0)) q;
\echo === LABDRIFT actual_kalshi_live_fills
SELECT 'LABDRIFT|actual_kalshi_live_fills#cols|' || (SELECT json_agg(e.key) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT count(*)::int AS n FROM kalshi_live_fills  WHERE observed_at >= to_timestamp(1789936020.0)    AND observed_at <= to_timestamp(1791145620.0)) q LIMIT 1;
SELECT 'LABDRIFT|actual_kalshi_live_fills|' || (SELECT json_agg(e.value) FROM json_each(row_to_json(q)) e)::text AS line FROM (SELECT count(*)::int AS n FROM kalshi_live_fills  WHERE observed_at >= to_timestamp(1789936020.0)    AND observed_at <= to_timestamp(1791145620.0)) q;
